-      llvm::dbgs() << "----------------------------------------------\n";
-      llvm::dbgs() << "MaskAnalysis: no mask or failed to analyze mask.\n";
-      llvm::dbgs() << "oldMask:" << oldMask << "\n";
-      maskState.dump();
-      llvm::dbgs() << "----------------------------------------------\n";
-    });
-    InFlightDiagnostic diag =
-        emitWarning(loc) << "MaskAnalysis: failed to analyze load/store mask.";
-    return nullptr;
