+static bool moduleHasCubeOps(ModuleOp moduleOp) {
+  bool existDot = false;
+  moduleOp.walk([&](Operation *op) {
+    if (isa<triton::DotOp, triton::DotScaledOp>(op)) {
+      existDot = true;
