+// CHECK: arith.cmpi sgt, %[[IF1]]#0, %{{.*}}
+// CHECK: arith.cmpi slt, %[[DEP1]], %{{.*}}
+// CHECK: %[[DEC0:.*]] = arith.subi %[[IF1]]#0, %{{.*}}
